<?php require __DIR__.'/includes/bootstrap.php';need_login();$s=$pdo->prepare('SELECT u.full_name,p.region,p.career_interest FROM users u JOIN profiles p ON p.user_id=u.id WHERE u.id=?');$s->execute([uid()]);$me=$s->fetch();$s=$pdo->prepare("SELECT COUNT(*) FROM connection_requests WHERE status='accepted' AND (sender_id=? OR receiver_id=?)");$s->execute([uid(),uid()]);$n=$s->fetchColumn();head('Your Community');?><section class="hero community-hero"><div class="hero-copy"><h1>Welcome, <?=e(explode(' ',$me['full_name'])[0])?></h1><p>Find job seekers in your region who share your goals.</p><a class="button" href="discover.php">Find members <span aria-hidden="true">→</span></a></div><div class="hero-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><img src="assets/community-illustration.svg" alt="People building a supportive community"></div></section><div class="grid community-stats"><div class="card stat-card"><span class="stat-icon">◎</span><h2><?= (int)$n ?></h2><p>Connections</p></div><div class="card stat-card"><span class="stat-icon">✳</span><h2><?=e($me['career_interest'])?></h2><p>Career interest</p></div><div class="card stat-card"><span class="stat-icon">⌖</span><h2><?=e($me['region'])?></h2><p>Region</p></div></div><section class="community-bottom"><div><h2>Complete your profile</h2><p>A complete profile helps members find and connect with you.</p></div><div class="bottom-actions"><a class="button" href="profile.php">Edit profile →</a><a class="text-link" href="requests.php">View connections</a></div></section><?php foot();?>